def subtotal(items):
    return sum(i['price'] for i in items)


def apply_discount(total, percent):
    return total - total * percent


def total_with_tax(items, tax_rate=0.2, discount=0):
    t = apply_discount(subtotal(items), discount)
    return round(t + t * tax_rate, 2)

