import unittest
from pricing import subtotal, apply_discount, total_with_tax

ITEMS = [{'price': 10, 'qty': 2}, {'price': 5, 'qty': 1}]


class T(unittest.TestCase):
    def test_subtotal_uses_quantity(self):
        self.assertEqual(subtotal(ITEMS), 25)

    def test_discount_is_a_percentage(self):
        self.assertEqual(apply_discount(100, 10), 90)

    def test_total(self):
        self.assertEqual(total_with_tax(ITEMS, 0.2, 10), 27.0)


if __name__ == '__main__':
    unittest.main()
